applyConfiguration.expression:
Object{


  spec: Object.spec{
    ?securityContext: object.spec.?securityContext.?seccompProfile.hasValue() ||
        (object.spec.containers + object.spec.?initContainers.orValue([])).all(c, c.?securityContext.?seccompProfile.hasValue())
      ? optional.none()
      : optional.of(Object.spec.securityContext{
          seccompProfile: Object.spec.securityContext.seccompProfile{type: "RuntimeDefault"}
        }),
    containers: object.spec.containers.map(c, Object.spec.containers{
      name: c.name,
      securityContext: Object.spec.containers.securityContext{
        ?allowPrivilegeEscalation: c.?securityContext.?allowPrivilegeEscalation.hasValue() ||
            c.?securityContext.?privileged.orValue(false) ||
            c.?securityContext.?capabilities.?add.orValue([]).exists(a, a == "SYS_ADMIN" || a == "CAP_SYS_ADMIN")
          ? optional.none() : optional.of(false),
        ?runAsNonRoot: variables.podRunAsNonRoot || c.?securityContext.?runAsNonRoot.hasValue() ||
            c.?securityContext.?runAsUser.orValue(variables.podRunAsUser) == 0
          ? optional.none() : optional.of(true)
      }
    }),
    ?initContainers: !has(object.spec.initContainers) ? optional.none() : optional.of(
      object.spec.initContainers.map(c, Object.spec.initContainers{
        name: c.name,
        securityContext: Object.spec.initContainers.securityContext{
          ?allowPrivilegeEscalation: c.?securityContext.?allowPrivilegeEscalation.hasValue() ||
              c.?securityContext.?privileged.orValue(false) ||
              c.?securityContext.?capabilities.?add.orValue([]).exists(a, a == "SYS_ADMIN" || a == "CAP_SYS_ADMIN")
            ? optional.none() : optional.of(false),
          ?runAsNonRoot: variables.podRunAsNonRoot || c.?securityContext.?runAsNonRoot.hasValue() ||
              c.?securityContext.?runAsUser.orValue(variables.podRunAsUser) == 0
            ? optional.none() : optional.of(true)
        }
      }))
  }
}
